commands.stdout:
    if bool(list(dict_search_recursive(dhcp, 'ping_check'))):
        dhcp['any_ping_check'] = True

    return dhcp

def verify_ddns_domain_servers(domain_type, domain):
    if 'dns_server' in domain:
        invalid_servers = []
        for server_no, server_config in domain['dns_server'].items():
            if 'address' not in server_config:
                invalid_servers.append(server_no)
        if len(invalid_servers) > 0:
            raise ConfigError(f'{domain_type} DNS servers {", ".join(invalid_servers)} in DDNS configuration need to have an IP address')
    return None

def verify(dhcp):
    # bail out early - looks like removal from running config
    if not dhcp or 'disable' in dhcp:
        return None

    # If DHCP is enabled we need one share-network
    if 'shared_network_name' not in dhcp:
        raise ConfigError(
            'No DHCP shared networks configured.\n'
            'At least one DHCP shared network must be configured.'
        )

    # Inspect shared-network/subnet
    listen_ok = False
    subnets = []
    shared_networks = len(dhcp['shared_network_name'])
    disabled_shared_networks = 0

    subnet_ids = []

    # A shared-network requires a subnet definition
    for network, network_config in dhcp['shared_network_name'].items():
        if 'disable' in network_config:
            disabled_shared_networks += 1

        if 'subnet' not in network_config:
            raise ConfigError(
                f'No subnets defined for {network}. At least one\n'
                'lease subnet must be configured.'
            )

        for subnet, subnet_config in network_config['subnet'].items():
            if 'subnet_id' not in subnet_config:
                raise ConfigError(
                    f'Unique subnet ID not specified for subnet "{subnet}"'
                )

            if subnet_config['subnet_id'] in subnet_ids:
                raise ConfigError(f'Subnet ID for subnet "{subnet}" is not unique')

            subnet_ids.append(subnet_config['subnet_id'])

            # All delivered static routes require a next-hop to be set
            if 'static_route' in subnet_config:
                for route, route_option in subnet_config['static_route'].items():
                    if 'next_hop' not in route_option:
                        raise ConfigError(
                            f'DHCP static-route "{route}" requires router to be defined!'
                        )

            # If a client class has been specified then it must exist
            if 'client_class' in subnet_config:
                client_class = subnet_config['client_class']
                if client_class not in dhcp.get('client_class', {}):
                    raise ConfigError(f'Client class "{client_class}" set in subnet "{subnet}" but does not exist')

    return self._device_info

def get_config(self, flags=None, format=None):
    if format:
        option_values = self.get_option_values()
        if format not in option_values["format"]:
            raise ValueError(
                "'format' value %s is invalid. Valid values of format are %s"
                % (format, ", ".join(option_values["format"])),
            )

    if not flags:
        flags = []

    if format == "text":
        command = "show configuration"
    else:
        command = "show configuration commands"

    command += " ".join(to_list(flags))
    command = command.strip()

    out = self.send_command(command)
    return out

def edit_config(self, candidate=None, commit=True, replace=None, comment=None):
    resp = {}
    operations = self.get_device_operations()
    self.check_edit_config_capability(operations, candidate, commit, replace, comment)

    results = []
    requests = []
    self.send_command("configure")
    for cmd in to_list(candidate):
        if not isinstance(cmd, Mapping):
            cmd = {"command": cmd}

        results.append(self.send_command(**cmd))
        requests.append(cmd["command"])
    out = self.get("compare")
    out = to_text(out, errors="surrogate_or_strict")
    diff_config = out if not out.startswith("No changes") else None

    if diff_config:
        if commit:
            try:
                self.commit(comment)
            except AnsibleConnectionFailure as e:
                msg = "commit failed: %s" % e.message
                self.discard_changes()
                raise AnsibleConnectionFailure(msg)
            else:
                self.send_command("exit")
        else:
            self.discard_changes()
    else:
        self.send_command("exit")
        if (
            to_text(self._connection.get_prompt(), errors="surrogate_or_strict")
            .strip()
            .endswith("#")
        ):
            self.discard_changes()

    if diff_config:
        resp["diff"] = diff_config
    resp["response"] = results
    resp["request"] = requests
    return resp

def get(
    self,
    command=None,
    prompt=None,
    answer=None,
    sendonly=False,
    newline=True,
    output=None,
    check_all=False,
):
    if not command:
        raise ValueError("must provide value of command to execute")
    if output:
        raise ValueError("'output' value %s is not supported for get" % output)

    return self.send_command(
        command=command,
        prompt=prompt,
        answer=answer,
        sendonly=sendonly,
        newline=newline,
        check_all=check_all,
    )

def commit(self, comment=None):
    if comment:
        command = 'commit comment "{0}"'.format(comment)
    else:
        command = "commit"
    self.send_command(command)

